window.CanopyIsTestnetRoute=()=>page==='testnet'||(['swap','bridge'].includes(page)&&tradeMode==='testnet');
function trade(bridge=false){const tabs=`<div class="transaction-mode" role="group" aria-label="Transaction mode"><button data-trade-mode="testnet" aria-pressed="${tradeMode==='testnet'}">Testnet · wallet transactions</button><button data-trade-mode="demo" aria-pressed="${tradeMode==='demo'}">Simulation preview</button></div>`;return tabs+(tradeMode==='testnet'?(window.CanopyTestnet?.view(bridge?'bridge':'swap')||'<p>Loading wallet tools…</p>'):demoTrade(bridge))}
function demoTrade(bridge=false){return heading(bridge?'Bridge':'Swap',bridge?'Move assets between networks.':'Swap tokens. Keep the market in view.')+`<div class="testnet-invite"><span>Try a real wallet-signed transaction with test ETH.</span><a href="#testnet">Open testnet workspace <svg class="outbound-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 11 11 5M5 5h6v6"/></svg></a></div><div class="page-grid"><section class="card trade-card"><div class="trade-tabs"><a href="#swap" class="${!bridge?'active':''}">Swap</a><a href="#bridge" class="${bridge?'active':''}">Bridge</a></div>${bridge?`<div class="network-row"><label>From network<select class="network-select" id="from-network"><option>Ethereum</option><option>Arbitrum</option><option>Base</option><option>Robinhood Chain</option></select></label><label>To network<select class="network-select" id="to-network"><option>Robinhood Chain</option><option>Ethereum</option><option>Arbitrum</option><option>Base</option></select></label></div>`:''}<div class="field-box"><div class="field-top"><span>You ${bridge?'bridge':'pay'}</span><span id="balance-label">Balance: ${num(state.balances[bridge?'USDC':'ETH'])}</span></div><div class="amount-row"><input aria-label="Amount to ${bridge?'bridge':'swap'}" id="amount" type="number" min="0" step="any" placeholder="0.00" value="${bridge?'100':'1'}"><span id="pay-token-logo" class="inline-token"></span><select aria-label="Pay asset" id="from-asset">${['ETH','USDC','SOL','BTC'].map(s=>`<option ${s===(bridge?'USDC':'ETH')?'selected':''}>${s}</option>`).join('')}</select></div><div class="field-bottom"><span id="pay-usd"></span><button id="max">Use max</button></div></div><button class="switch" id="reverse" aria-label="Reverse ${bridge?'networks':'assets'}"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 17V7m-3 3 3-3 3 3m5-3v10m-3-3 3 3 3-3"/></svg></button><div class="field-box"><div class="field-top"><span>You receive</span><span>Estimated</span></div><div class="amount-row"><input aria-label="Estimated received amount" id="receive" readonly><span id="receive-token-logo" class="inline-token"></span><select aria-label="Receive asset" id="to-asset" ${bridge?'disabled':''}>${['USDC','ETH','SOL','BTC'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field-bottom"><span id="receive-usd"></span><span>${bridge?'Destination wallet · Same address':'Includes demo fee'}</span></div></div><div class="trade-details"><div><span>${bridge?'Estimated arrival':'Exchange rate'}</span><b id="rate">~2 minutes</b></div><div><span>${bridge?'Bridge fee':'Trading fee'}</span><b>${bridge?'0.1%':'0.3%'}</b></div><div><span>Network fee</span><b>Illustrative · $0.08</b></div>${bridge?'':`<div><label for="slippage">Slippage tolerance</label><select class="network-select" id="slippage"><option>0.5%</option><option>1%</option><option>2%</option></select></div>`}</div><button class="primary full" id="review-trade">Review ${bridge?'bridge':'swap'}</button><p class="form-note">Simulated ${bridge?'bridge route':'quote'} · No wallet signature or real funds.</p></section><section class="trade-context">${bridge?`<div class="card route-panel"><div class="card-top"><h2>Transfer route</h2><span class="tag">Simulation</span></div><div class="route-stops"><div><span class="route-icon" id="route-from-icon">${CanopyUI.network('Ethereum')}</span><div><small>FROM</small><h3 id="route-from">Ethereum</h3></div></div><div class="route-line"><i></i><span>Bridge</span><i></i></div><div><span class="route-icon destination" id="route-to-icon">${CanopyUI.network('Robinhood Chain')}</span><div><small>TO</small><h3 id="route-to">Robinhood Chain</h3></div></div></div><div class="route-steps"><div><span>1</span><div><h3>Review the route</h3><p>Check networks, fees, and the amount arriving.</p></div></div><div><span>2</span><div><h3>Confirm the transfer</h3><p>This preview records a simulated transfer.</p></div></div><div><span>3</span><div><h3>Track arrival</h3><p>Network confirmations will appear here when connected.</p></div></div></div></div>`:`<div class="card context-chart"><div class="card-top"><h2 class="chart-asset-title">${CanopyUI.token('ETH')}ETH / USD</h2><span class="tag">Market chart</span></div>${liveChart('ETH','swap-chart')}</div>`}<div class="recent-panel"><div class="card-top"><h2>Recent ${bridge?'transfers':'swaps'}</h2><button class="quiet" data-go="activity">View activity</button></div>${activityRows()}</div></section></div>`}
function markets(){return heading('Markets','Price action, watchlists, and what’s moving.',`<span class="tag">Charts powered by TradingView</span>`)+`<div class="market-controls"><div class="segments">${[['stocks','Stocks'],['crypto','Crypto'],['memes','Trending memes']].map(([v,n])=>`<button class="${market===v?'active':''}" data-market="${v}">${n}</button>`).join('')}</div><input class="search" id="search" aria-label="Search markets" placeholder="Search name or symbol"></div><section class="market-terminal"><div class="market-sidebar"><div class="card-top"><h2>${market==='memes'?'Meme watch':market==='stocks'?'Stock watch':'Crypto watch'}</h2><span class="data-caption">Sample list</span></div><div id="market-rows">${marketRows('')}</div></div><div class="market-chart-panel"><div class="card-top"><h2 id="selected-market">${coin(assets.find(a=>a.symbol===selectedSymbol))}${selectedSymbol} / ${market==='memes'?'USDT':'USD'}</h2><span class="data-caption">Exchange data · May be delayed</span></div><div id="market-live">${liveChart(selectedSymbol,'markets-chart')}</div></div></section><div class="market-bottom"><span>★ Pin assets to your portfolio watchlist.</span><span>Quotes in this list are samples. Open a chart for exchange data.</span></div>`}
function marketRows(q){let list=assets.filter(a=>a.type===market&&`${a.name} ${a.symbol}`.toLowerCase().includes(q.toLowerCase()));return list.length?list.map(a=>`<div class="market-row ${selectedSymbol===a.symbol?'selected':''}"><button class="pin ${watchlist.includes(a.symbol)?'pinned':''}" data-pin="${a.symbol}" aria-label="${watchlist.includes(a.symbol)?'Unpin':'Pin'} ${a.name}">${watchlist.includes(a.symbol)?'★':'☆'}</button><button class="market-select" data-select-market="${a.symbol}">${assetName(a)}<span>${money(a.price,a.price<.01?7:2)}<small>${chg(a)}</small></span></button></div>`).join(''):'<div class="empty">No matching assets.</div>'}
function stake(){return heading('Staking preview','Simulation only — staking is not connected to a testnet protocol.')+`<div class="staking-hero"><section class="card staking-total"><div class="label">Your staked balance</div><div class="big-number">${money(state.staked)}</div><div class="change">✳ &nbsp; Earning across your demo positions</div><div class="stat-row"><div><span class="label">Rewards available</span><div class="value">${money(state.rewards)}</div></div><div><span class="label">Illustrative APY</span><div class="value">4.80%</div></div><div><button class="secondary" data-action="claim" ${state.rewards<=0?'disabled':''}>Claim rewards</button></div></div></section><section class="card earn-card"><div class="label">Position overview</div><h2>3 strategies.<br>One place to manage them.</h2><p>Compare estimated yields and unstaking periods. All positions below are simulated.</p></section></div><div class="card-top" style="margin:30px 0 20px"><h2>Explore staking</h2><span class="tag">Demo opportunities</span></div><div class="staking-cards">${[['ETH','3.8','~5 days'],['SOL','6.4','~3 days'],['BTC','2.2','~7 days']].map(([s,r,u])=>{let a=assets.find(x=>x.symbol===s);return `<section class="card staking-card">${assetName(a)}<div><div class="apy">${r}<span style="font-size:20px">%</span></div><p>Illustrative annual yield</p></div><p style="margin-top:20px">${s==='BTC'?'Wrapped BTC strategy':'Network staking'}<br>Unstaking: ${u}<br>Demo balance: ${num(state.balances[s])} ${s}</p><button class="secondary" data-stake="${s}">Stake ${s}</button></section>`}).join('')}</div><p class="form-note">Illustrative rates only. Strategies are not connected to protocols; no returns are promised.</p>`}
function activityRows(){return state.activity.length?state.activity.slice().reverse().map(a=>`<div class="activity-row"><span class="coin">${a.type==='Swap'?'⇄':a.type==='Stake'?'✳':'◈'}</span><div>${a.type}<small>${a.detail}</small></div><span class="positive">Simulated<small>${a.time}</small></span></div>`).join(''):'<div class="empty"><div style="font-size:30px;margin-bottom:14px">◷</div>No moves yet.<small>Your demo swaps, bridges, and staking activity will appear here.</small></div>'}
function activity(){return heading('Activity','Transfers, swaps, and staking history.')+`<section class="card activity-card">${activityRows()}</section>`}
function render(){range='1W';page=location.hash.slice(1).split('/')[0]||'portfolio';if(!names[page])page='portfolio';nav();$('#main').innerHTML=({rh:()=>window.CanopyRH?.view()||'<p>Loading markets…</p>',testnet:()=>window.CanopyTestnet?.view()||'<p>Loading wallet tools…</p>',portfolio,markets,swap:()=>trade(false),bridge:()=>trade(true),stake,activity})[page]();if(['swap','bridge'].includes(page)&&tradeMode==='demo'){updateQuote();for(const el of [$('#amount'),$('#from-asset'),$('#to-asset'),$('#from-network'),$('#to-network')].filter(Boolean))el.addEventListener('input',updateQuote);$('#max').onclick=()=>{$('#amount').value=state.balances[$('#from-asset').value];updateQuote()};$('#reverse').onclick=()=>{if(page==='bridge'){let a=$('#from-network').value;$('#from-network').value=$('#to-network').value;$('#to-network').value=a}else{let a=$('#from-asset').value;$('#from-asset').value=$('#to-asset').value;$('#to-asset').value=a}updateQuote()};$('#review-trade').onclick=reviewTrade}if(page==='markets')$('#search').oninput=e=>$('#market-rows').innerHTML=marketRows(e.target.value);hydrateCharts();if(page==='rh')window.CanopyRH?.mount();if(window.CanopyIsTestnetRoute())window.CanopyTestnet?.mount();for(const b of document.querySelectorAll('[data-trade-mode]'))b.onclick=()=>{tradeMode=b.dataset.tradeMode;render()};CanopyUI.enter($('#main'));}
function updateQuote(){let f=$('#from-asset').value;if(page==='bridge'){$('#to-asset').value=f;$('#route-from').textContent=$('#from-network').value;$('#route-to').textContent=$('#to-network').value;$('#route-from-icon').innerHTML=CanopyUI.network($('#from-network').value);$('#route-to-icon').innerHTML=CanopyUI.network($('#to-network').value);}let t=$('#to-asset').value;$('#pay-token-logo').innerHTML=CanopyUI.token(f);$('#receive-token-logo').innerHTML=CanopyUI.token(t);let fa=assets.find(a=>a.symbol===f),ta=assets.find(a=>a.symbol===t),amount=Number($('#amount').value),fee=page==='bridge'?.001:.003;let received=amount*fa.price/ta.price*(1-fee);$('#receive').value=Number(received.toFixed(7));$('#balance-label').textContent=`Balance: ${num(state.balances[f])}`;$('#pay-usd').textContent=money(amount*fa.price);$('#receive-usd').textContent=money(received*ta.price);if(page==='swap')$('#rate').textContent=`1 ${f} = ${num(fa.price/ta.price)} ${t}`;let error=!Number.isFinite(amount)||amount<=0?'Enter an amount':amount>state.balances[f]?'Insufficient demo balance':page==='swap'&&f===t?'Choose different assets':page==='bridge'&&$('#from-network').value===$('#to-network').value?'Choose different networks':'';$('#review-trade').disabled=!!error;$('#review-trade').style.opacity=error?.5:1;$('#review-trade').textContent=error||`Review ${page}`;}
function showModal(html){$('#modal').classList.remove('chart-modal');$('#modal-content').innerHTML=`<button class="close" aria-label="Close dialog">×</button>${html}`;$('#modal').showModal();CanopyUI.enter($('#modal-content'));$('.close').onclick=()=>$('#modal').close()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function log(type,detail){state.activity.push({type,detail,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'})});persist()}
function reviewTrade(){let f=$('#from-asset').value,t=$('#to-asset').value,a=Number($('#amount').value),out=Number($('#receive').value),bridge=page==='bridge',route=bridge?`${$('#from-network').value} to ${$('#to-network').value}`:'';showModal(`<div class="modal-icon">${bridge?'◎':'⇄'}</div><h2>Review your ${page}</h2><p>${bridge?route:'Check amounts and fees before confirming.'}</p><div class="trade-details"><div><span>You pay</span><b>${num(a)} ${f}</b></div><div><span>You receive</span><b>${num(out)} ${t}</b></div><div><span>Mode</span><b>Simulation only</b></div></div><p>${bridge?'This records a demo bridge route; destination network balances are not connected.':'This updates your local demo balances.'} No real assets will move.</p><button class="primary full" id="confirm">Simulate ${page}</button>`);$('#confirm').onclick=async()=>{const button=$('#confirm');button.disabled=true;button.textContent='Simulating…';const progress=document.createElement('div');progress.innerHTML=CanopyUI.progress(bridge?'Simulating your bridge':'Simulating your swap','Preview only · No onchain transaction is sent.');button.before(progress);CanopyUI.transaction(bridge?'Bridge simulation in progress':'Swap simulation in progress');await new Promise(resolve=>setTimeout(resolve,1500));if(!bridge){state.balances[f]-=a;state.balances[t]+=out}log(bridge?'Bridge':'Swap',bridge?`${num(a)} ${f} · ${route}`:`${num(a)} ${f} to ${num(out)} ${t}`);$('#modal').close();render();toast(`${bridge?'Bridge':'Swap'} simulation complete`);CanopyUI.transaction(`${bridge?'Bridge':'Swap'} simulation complete`,false)}}
function assetDetail(symbol){const a=assets.find(a=>a.symbol===symbol);showModal(`<div class="asset-name" style="margin-bottom:22px">${coin(a)}<div><h2 style="margin:0">${a.name}</h2><small>${a.symbol} · Exchange market chart</small></div></div>${liveChart(symbol,'detail-chart')}<p>Chart quotes come from TradingView and may be delayed by exchange. Your demo balances use sample prices.</p><div class="modal-actions"><button class="secondary" data-pin="${symbol}">${watchlist.includes(symbol)?'Remove from watchlist':'Add to watchlist'}</button>${['ETH','BTC','SOL','USDC'].includes(symbol)?'<button class="primary" id="trade-asset">Open swap</button>':''}</div>`);$('#modal').classList.add('chart-modal');hydrateCharts();if($('#trade-asset'))$('#trade-asset').onclick=()=>{$('#modal').close();location.hash='swap'}}
function stakeModal(s){const a=assets.find(a=>a.symbol===s);showModal(`<div class="modal-icon">✳</div><h2>Stake ${s}</h2><p>This simulation moves assets from your available balance to your staked total.</p><label class="modal-label" for="stake-amount">Amount · Available ${num(state.balances[s])} ${s}</label><input class="modal-input" type="number" min="0" step="any" id="stake-amount" value="${Math.min(1,state.balances[s])}"><p id="stake-error" class="negative"></p><button class="primary full" id="confirm-stake">Simulate stake</button>`);$('#confirm-stake').onclick=()=>{let amount=Number($('#stake-amount').value);if(!Number.isFinite(amount)||amount<=0||amount>state.balances[s]){$('#stake-error').textContent='Enter an amount within your available balance.';return}state.balances[s]-=amount;state.staked+=amount*a.price;log('Stake',`${num(amount)} ${s}`);$('#modal').close();render();toast(`${num(amount)} ${s} staked in demo`)}}
function funds(action){showModal(`<div class="modal-icon">◈</div><h2>${action==='send'?'Send demo funds':'Add demo funds'}</h2><p>${action==='send'?'Simulate a USDC transfer to an address.':'Top up your demo USDC balance to explore Canopy.'} No real money moves.</p>${action==='send'?'<label class="modal-label" for="recipient">Recipient address</label><input class="modal-input" id="recipient" placeholder="0x…">':''}<label class="modal-label" for="fund-amount">Amount in USDC</label><input class="modal-input" id="fund-amount" type="number" min="0" value="1000"><p id="fund-error"></p><button class="primary full" id="confirm-fund">${action==='send'?'Simulate send':'Add demo USDC'}</button>`);$('#confirm-fund').onclick=()=>{let a=Number($('#fund-amount').value);if(!Number.isFinite(a)||a<=0||a>1e8||(action==='send'&&a>state.balances.USDC)){$('#fund-error').textContent='Enter a valid amount within your balance and demo limits.';return}if(action==='send'&&!/^0x[a-fA-F0-9]{40}$/.test($('#recipient').value)){$('#fund-error').textContent='Enter a valid 42-character EVM address.';return}state.balances.USDC+=action==='send'?-a:a;log(action==='send'?'Send':'Deposit',`${num(a)} USDC`);$('#modal').close();render();toast('Demo balance updated')}}
document.addEventListener('click',e=>{const b=e.target.closest('button, tr[data-asset]');if(!b)return;if(b.dataset.go)location.hash=b.dataset.go;if(b.dataset.range){range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(el=>el.classList.toggle('active',el.dataset.range===range));$('#portfolio-chart').innerHTML=chart(['1D','1W','1M','3M','1Y','ALL'].indexOf(range));let labels={'1D':['+$486.28 (0.58%)','today','00:00'],'1W':['+$2,184.32 (2.66%)','this week','NOV 11'],'1M':['+$6,831.43 (8.81%)','this month','OCT 18'],'3M':['+$12,251.80 (17.02%)','past 3 months','AUG 18'],'1Y':['+$24,384.17 (40.63%)','this year','NOV 2025'],'ALL':['+$31,844.20 (60.78%)','all time','JUN 2024']}[range];$('#portfolio-change').innerHTML=`<svg class="outbound-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 11 11 5M5 5h6v6"/></svg> &nbsp;${labels[0]} <span>${labels[1]}</span>`;$('#chart-date').textContent=labels[2]}if(b.dataset.market){market=b.dataset.market;selectedSymbol=assets.find(a=>a.type===market).symbol;render()}if(b.dataset.hold){holdTab=b.dataset.hold;render()}if(b.dataset.mini){miniTab=b.dataset.mini;render()}if(b.dataset.asset)assetDetail(b.dataset.asset);if(b.dataset.detailRange){$('#modal').close();assetDetail(b.dataset.symbol,b.dataset.detailRange)}if(b.dataset.stake)stakeModal(b.dataset.stake);if(['send','deposit'].includes(b.dataset.action))funds(b.dataset.action);if(b.dataset.action==='claim'){showModal(`<div class="modal-icon">✳</div><h2>Claim your demo rewards</h2><p>Move ${money(state.rewards)} in illustrative rewards into your available USDC balance.</p><button class="primary full" id="confirm-claim">Simulate claim</button>`);$('#confirm-claim').onclick=()=>{let rewards=state.rewards;state.balances.USDC+=rewards;state.rewards=0;log('Claim',`${money(rewards)} USDC rewards`);$('#modal').close();render();toast('Demo rewards claimed')}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-asset]'))assetDetail(e.target.dataset.asset)});
$('#wallet').onclick=()=>showModal(`<div class="modal-icon">◈</div><h2>Your demo wallet</h2><p>This is a sample account for exploring Canopy. Wallet connection and signing will be added with mainnet integration.</p><div class="address">0x71C7656EC7ab88b098defB751B7401B5f6d8976F</div><p>Demo account · Wallet signing is not enabled.</p>`);
$('#reset').onclick=()=>{showModal('<h2>Start fresh?</h2><p>This resets only your local demo balances and simulated activity.</p><button class="primary full" id="confirm-reset">Reset demo</button>');$('#confirm-reset').onclick=()=>{localStorage.removeItem('canopy-state');location.reload()}};
function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem('canopy-theme',theme);$('#appearance').setAttribute('aria-label',`Switch to ${theme==='light'?'dark':'light'} mode`);$('#appearance').title=`Switch to ${theme==='light'?'dark':'light'} mode`;$('#mobile-theme').setAttribute('aria-label',`Switch to ${theme==='light'?'dark':'light'} mode`);$('#appearance').innerHTML=theme==='light'?CanopyUI.moon:CanopyUI.sun;$('#mobile-theme').innerHTML=theme==='light'?CanopyUI.moon:CanopyUI.sun;document.querySelectorAll('[data-tv]').forEach(el=>{delete el.dataset.loaded;el.innerHTML=''});hydrateCharts()}
$('#mobile-theme').onclick=()=>$('#appearance').click();
$('#appearance').onclick=()=>setTheme(document.documentElement.dataset.theme==='light'?'dark':'light');
$('#global-search').onclick=()=>{location.hash='markets';render();$('#search').focus()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#global-search').click()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pin){const symbol=b.dataset.pin;watchlist=watchlist.includes(symbol)?watchlist.filter(x=>x!==symbol):[...watchlist,symbol];localStorage.setItem('canopy-watchlist',JSON.stringify(watchlist));if(page==='markets')$('#market-rows').innerHTML=marketRows($('#search').value);if($('#modal').open){b.textContent=watchlist.includes(symbol)?'Remove from watchlist':'Add to watchlist'}toast(watchlist.includes(symbol)?`${symbol} added to watchlist`:`${symbol} removed from watchlist`)}if(b.dataset.selectMarket){selectedSymbol=b.dataset.selectMarket;$('#selected-market').innerHTML=coin(assets.find(a=>a.symbol===selectedSymbol))+selectedSymbol+' / '+(market==='memes'?'USDT':'USD');$('#market-live').innerHTML=liveChart(selectedSymbol,'markets-chart');$('#market-rows').innerHTML=marketRows($('#search').value);hydrateCharts()}});
setTheme(document.documentElement.dataset.theme||'light');
